<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole(['counter_staff','handling_staff','supervisor','system_admin']);$pdo=$db->getConnection();$q=trim($_GET['q']??'');$rows=[];if($q!==''){$p='%'.$q.'%';$stmt=$pdo->prepare("SELECT b.*,u.full_name,f.flight_number,bt.type_name FROM baggage b JOIN users u ON b.passenger_id=u.id JOIN flights f ON b.flight_id=f.id JOIN baggage_types bt ON b.baggage_type_id=bt.id WHERE b.baggage_code LIKE ? OR u.full_name LIKE ? OR f.flight_number LIKE ? ORDER BY b.created_at DESC LIMIT 50");$stmt->execute([$p,$p,$p]);$rows=$stmt->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Baggage Search</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><a href="dashboard.php">← Dashboard</a><h2>Baggage Search</h2><form class="row g-2 my-3"><div class="col-md-9"><input class="form-control" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Baggage code, passenger or flight"></div><div class="col-md-3"><button class="btn btn-primary w-100">Search</button></div></form><div class="card"><table class="table mb-0"><thead><tr><th>Code</th><th>Passenger</th><th>Flight</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['baggage_code'])?></td><td><?=htmlspecialchars($r['full_name'])?></td><td><?=htmlspecialchars($r['flight_number'])?></td><td><?=htmlspecialchars($r['type_name'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><a href="tracking_update_simple.php?baggage_id=<?=intval($r['id'])?>">Tracking</a></td></tr><?php endforeach;?></tbody></table></div></div></body></html>